-- Category pictograms as data: an icon library (SVG path data on a 24×24 grid, filled even-odd in the category's
-- colour) that admins manage, so every app draws the same pictograms and new ones need no app release.
-- Seeded with the pictograms the iOS app drew; categories point at an icon (null = draw the shape).
create table icons (
  id         text primary key check (id ~ '^[a-z][a-z0-9_]{1,31}$'),
  label      text not null check (length(label) between 1 and 40),
  path       text not null check (length(path) between 1 and 8000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- Who changed it last. No foreign key, like categories.updated_by.
  updated_by uuid
);

create unique index icons_label_key on icons (lower(label));

