alter table categories add column icon text references icons (id);

update categories set icon = v.icon
from (values
  ('food', 'plate'), ('coffee', 'cup'), ('bar', 'cocktail'), ('club', 'music'), ('kids', 'teddy'),
  ('culture', 'palette'), ('nature', 'pine'), ('sport', 'ball'), ('shopping', 'bag'), ('hotel', 'bed'),
  ('other', 'shapes')
) as v(id, icon)
where categories.id = v.id;

-- New categories go before "other", which stays last (only if admins have not changed the order).
update categories set position = position + 4 where id = 'other' and position = 11;
insert into categories (id, label, color, shape, icon, position) values
  ('brewery',   'Pivovar',    '#F2B900', 'half',     'beer',   11),
  ('museum',    'Muzeum',     '#141414', 'triangle', 'museum', 12),
  ('pool',      'Basen',      '#1D4FA0', 'circle',   'pool',   13),
  ('curiosity', 'Osobliwość', '#D7301F', 'ring',     'eye',    14)
on conflict do nothing;
